import json
def gql(schema, root, query, variables='{}', extra='', output='JSON.stringify(result.data)'):
 return 'import { buildSchema, graphql } from "graphql";\nconst schema = buildSchema('+json.dumps(schema)+');\n'+extra+'\nconst rootValue = '+root+';\nconst result = await graphql({ schema, rootValue, source: '+json.dumps(query)+', variableValues: '+variables+' });\nconsole.log('+output+');\n'
def ws(server_steps, client_steps, size=1024):
 return 'import WebSocket, { WebSocketServer } from "ws";\nconst server = new WebSocketServer({ host: "127.0.0.1", port: 8080, maxPayload: '+str(size)+' });\nawait new Promise(resolve => server.once("listening", resolve));\n'+server_steps+'\nconst client = new WebSocket("ws://127.0.0.1:8080");\n'+client_steps+'\n'
read_message='client.on("message", data => { console.log(data.toString()); client.close(); server.close(); });'
course('graphql','GraphQL','javascript','Examples use GraphQL.js 16 and Node.js 20 or later.','In a practice folder run npm init -y and npm install graphql@16. Save one example as lesson.mjs and run node lesson.mjs. These examples execute queries locally and do not need an HTTP server.','GraphQL lets a client ask for specific fields of data. A schema describes what can be asked for.',[
L('first-query','Ask for one field','A schema names allowed fields. The resolver supplies a value for greeting.',gql('type Query { greeting: String! }','{ greeting: () => "Hello, Asha!" }','{ greeting }'),'{"greeting":"Hello, Asha!"}','Change the resolver greeting.','A query can only ask for fields declared in the schema.'),
L('selected-fields','Choose part of an object','The query picks title and leaves out pages. The resolver still holds both fields.',gql('type Book { title: String!, pages: Int! } type Query { book: Book! }','{ book: () => ({ title: "Moon Trip", pages: 24 }) }','{ book { title } }'),'{"book":{"title":"Moon Trip"}}','Ask for pages too.','GraphQL object fields need a selection of their inner fields.'),
L('arguments','Give a field an input','An argument supplies a value to a field. The resolver receives it in an object.',gql('type Query { twice(n: Int!): Int! }','{ twice: ({ n }) => n * 2 }','{ twice(n: 4) }'),'{"twice":8}','Ask for twice(n: 7).','The input must match the argument type.'),
L('variables','Keep query text and values apart','A variable lets one query be reused with different values. Its value is supplied separately.',gql('type Query { twice(n: Int!): Int! }','{ twice: ({ n }) => n * 2 }','query Double($n: Int!) { twice(n: $n) }','{ n: 4 }'),'{"twice":8}','Change variable n to 7 without changing the query.','A declared required variable must be supplied.'),
L('lists','Read several objects','Square brackets describe a list type. The query selects title for each book.',gql('type Book { title: String! } type Query { books: [Book!]! }','{ books: () => [{ title: "Moon Trip" }, { title: "Sun Trip" }] }','{ books { title } }'),'{"books":[{"title":"Moon Trip"},{"title":"Sun Trip"}]}','Add a third book to the resolver result.','The list item shape must match the schema type.'),
L('aliases','Give results different names','Aliases name two uses of the same field so both results can appear together.',gql('type Query { twice(n: Int!): Int! }','{ twice: ({ n }) => n * 2 }','{ small: twice(n: 2) big: twice(n: 4) }'),'{"small":4,"big":8}','Add an alias called larger for input 5.','Two different arguments on one field need distinct response names.'),
L('fragments','Reuse a field selection','A fragment gives a group of fields a name. The query spreads that group onto a Book.',gql('type Book { title: String!, pages: Int! } type Query { book: Book! }','{ book: () => ({ title: "Moon Trip", pages: 24 }) }','{ book { ...BookCard } } fragment BookCard on Book { title pages }'),'{"book":{"title":"Moon Trip","pages":24}}','Remove pages from the fragment.','A fragment has to apply to the type at that position.'),
L('enums','Use a named set of choices','An enum limits a value to named choices. GREEN is a schema label, not arbitrary text.',gql('enum Light { RED GREEN } type Query { light: Light! }','{ light: () => "GREEN" }','{ light }'),'{"light":"GREEN"}','Return RED instead.','The resolver result must match an enum value.'),
L('mutations','Ask for a change','A mutation names a write action. This local example changes one in-memory score.',gql('type Query { score: Int! } type Mutation { setScore(value: Int!): Int! }','{ score: () => score, setScore: ({ value }) => { score = value; return score; } }','mutation { setScore(value: 8) }',extra='let score = 3;'),'{"setScore":8}','Set the value to 6.','The resolver must implement the change; declaring a mutation alone does not save data.'),
L('non-null','Require a value','The exclamation mark means a field must not be null. This resolver breaks that rule, so GraphQL reports an error.',gql('type Query { name: String! }','{ name: () => null }','{ name }',output='result.errors[0].message'),'Cannot return null for non-nullable field Query.name.','Return Asha instead and print result.data.','Use non-null only when the resolver can honour that promise.'),
L('directives','Choose fields with a flag','The include directive can choose whether a field is requested. The flag is false here.',gql('type Query { title: String!, pages: Int! }','{ title: () => "Moon Trip", pages: () => 24 }','query Card($details: Boolean!) { title pages @include(if: $details) }','{ details: false }'),'{"title":"Moon Trip"}','Set details to true.','The directive input is Boolean, not the text "true" or "false".'),
L('input-objects','Group several inputs','An input type groups values sent into a mutation. It is separate from an output object type.',gql('input BookInput { title: String! } type Query { ready: Boolean! } type Mutation { createBook(book: BookInput!): String! }','{ ready: () => true, createBook: ({ book }) => book.title }','mutation { createBook(book: { title: "Moon Trip" }) }'),'{"createBook":"Moon Trip"}','Change the input title.','This example returns the title only; a real resolver needs storage to save a book.')])
course('rest-api','REST API Development','http','Examples use HTTP semantics and JSON. They are worked exchanges, not a live service.','Read the request and response pairs in a text editor. They show only headers useful to each idea. No server, account or installation is needed for these exercises; /books is an imaginary practice API.','A REST-style API names resources with URLs and uses HTTP methods to read or change them.',[
L('resources','Name a resource','A resource is a thing an API exposes. /books/1 names one book, while /books names a collection.','GET /books/1 HTTP/1.1\nHost: example.test\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":1,"title":"Moon Trip"}','Book 1 is returned with status 200.','Write a URL for book 2.','Use resource names clearly; a URL should identify what is being addressed.'),
L('get','Read without changing data','GET asks to read a resource. Reading this collection does not add or remove books.','GET /books HTTP/1.1\nHost: example.test\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n[{"id":1,"title":"Moon Trip"}]','A list with one book is returned.','Write the response for a collection with two books.','Do not design a GET route that deletes a record.'),
L('post','Create a resource','POST sends data for the collection to handle. A successful creation often returns 201 and a Location header.','POST /books HTTP/1.1\nHost: example.test\nContent-Type: application/json\n\n{"title":"Sun Trip"}\n\nHTTP/1.1 201 Created\nLocation: /books/2\nContent-Type: application/json\n\n{"id":2,"title":"Sun Trip"}','Book 2 is created; its location is /books/2.','Write a POST for another title.','A repeated POST can create another item unless the API provides a duplicate-prevention rule.'),
L('put','Replace a known resource','PUT supplies the desired representation at a known URL. This example replaces the book title and page count.','PUT /books/1 HTTP/1.1\nHost: example.test\nContent-Type: application/json\n\n{"title":"Moon Trip","pages":30}\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":1,"title":"Moon Trip","pages":30}','Book 1 now has 30 pages.','Write a replacement with 40 pages.','Know whether the API treats omitted fields as removed when using PUT.'),
L('patch','Change part of a resource','PATCH can send only changes. This example uses JSON Merge Patch to change the page count.','PATCH /books/1 HTTP/1.1\nHost: example.test\nContent-Type: application/merge-patch+json\n\n{"pages":30}\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":1,"title":"Moon Trip","pages":30}','Only the page count is changed to 30.','Write a patch for the title.','PATCH formats have different rules; name the media type you support.'),
L('delete','Remove a resource','DELETE asks to remove the target resource. A 204 success response has no body.','DELETE /books/1 HTTP/1.1\nHost: example.test\n\nHTTP/1.1 204 No Content','The book is removed; the response body is empty.','Describe what a later GET might return.','Do not attach a JSON body to a 204 response.'),
L('not-found','Report an unknown item','404 means the requested resource was not found. A short error body can help a client explain the problem.','GET /books/99 HTTP/1.1\nHost: example.test\n\nHTTP/1.1 404 Not Found\nContent-Type: application/json\n\n{"error":"Book not found"}','The API reports a missing book with status 404.','Write a useful message for an unknown author.','Do not return 200 for every outcome; clients use status codes.'),
L('filters','Choose matching results','A query string can describe a filter. The exact parameter names belong to the API design.','GET /books?colour=blue HTTP/1.1\nHost: example.test\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n[{"id":1,"colour":"blue"}]','Only matching blue books are returned.','Design a filter for books with at least 20 pages.','Document filter rules rather than making clients guess them.'),
L('pagination','Read a small page of results','Pagination divides a large collection into smaller pieces. This example returns a next link.','GET /books?limit=1 HTTP/1.1\nHost: example.test\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"items":[{"id":1}],"next":"/books?after=1&limit=1"}','The client gets one item and a link for the next page.','Write the request using the next link.','Use a stable ordering so items do not jump between pages.'),
L('content-types','Describe the body format','Content-Type says what format a body uses. Accept says which response formats the client can understand.','GET /books/1 HTTP/1.1\nHost: example.test\nAccept: application/json\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id":1}','The response body is JSON.','Explain the difference between Accept and Content-Type.','JSON text needs valid quoting; a header alone does not make invalid text valid JSON.'),
L('idempotence','Repeat a request safely','An idempotent operation has the same intended final effect when repeated. Setting pages to 30 twice leaves it at 30.','PUT /books/1 HTTP/1.1\nContent-Type: application/json\n\n{"title":"Moon Trip","pages":30}\n\n# Send the same PUT a second time.\n# Final stored representation:\n{"title":"Moon Trip","pages":30}','The page count remains 30 after both PUT requests.','Compare setting a count with adding one to a count.','Same final effect does not require every repeated response to have the same status.'),
L('conditional-get','Reuse an unchanged response','An ETag labels a version. If-None-Match asks whether that version is still current. A 304 has no new body.','GET /books/1 HTTP/1.1\nHost: example.test\nIf-None-Match: "book-v1"\n\nHTTP/1.1 304 Not Modified\nETag: "book-v1"','The client may reuse its cached book-v1 body.','Describe the reply when the resource has changed.','A client needs a cached body to reuse; 304 does not contain the resource data.')])
course('websockets','WebSockets','javascript','Examples use the ws 8 package and Node.js 20 or later on one computer.','Run npm init -y and npm install ws@8 in a practice folder. Save each example as lesson.mjs and run node lesson.mjs. Each file starts a local server and test client, prints a result, then closes both.','WebSockets keep a two-way connection open so either side can send messages without a fresh HTTP request.',[
L('connection','Receive a welcome message','The server sends text when a client connects. The client reads one message and closes.',ws('server.on("connection", socket => socket.send("Hello, Asha!"));',read_message),'Hello, Asha!','Change the welcome text.','A WebSocket server must be listening before a client can connect.'),
L('send','Send from the client','The open event means the connection is ready. Sending before it is ready can fail.',ws('server.on("connection", socket => socket.on("message", data => socket.send("Received: " + data.toString())));','client.on("open", () => client.send("Hi"));\n'+read_message),'Received: Hi','Send a different short message.','Wait for open before calling send.'),
L('echo','Return the same message','An echo server sends received text back unchanged.',ws('server.on("connection", socket => socket.on("message", data => socket.send(data.toString())));','client.on("open", () => client.send("Moon Trip"));\n'+read_message),'Moon Trip','Send Sun Trip instead.','Node ws receives Buffer data by default; turn text into a string.'),
L('json','Send structured message data','JSON can give a message named fields. The server reads score and doubles it.',ws('server.on("connection", socket => socket.on("message", data => { const message = JSON.parse(data.toString()); socket.send(JSON.stringify({ answer: message.score * 2 })); }));','client.on("open", () => client.send(JSON.stringify({ score: 4 })));\n'+read_message),' {"answer":8}'.strip(),'Send score 7.','Real message handlers need checks for invalid JSON and invalid fields.'),
L('field-checks','Check a message shape','A parsed object may still be missing a field. This example sends an empty object and gets a clear reply.',ws('server.on("connection", socket => socket.on("message", data => { const message = JSON.parse(data.toString()); socket.send(typeof message.text === "string" ? message.text : "Message needed"); }));','client.on("open", () => client.send("{}"));\n'+read_message),'Message needed','Send {"text":"Hi"} as JSON.','Parsing JSON and checking its field types are separate jobs.'),
L('broadcast','Send to connected clients','A broadcast visits each connected client. Only open sockets are ready to send.',ws('server.on("connection", socket => socket.on("message", data => { for (const peer of server.clients) { if (peer.readyState === WebSocket.OPEN) peer.send("News: " + data.toString()); } }));','client.on("open", () => client.send("Hello"));\n'+read_message),'News: Hello','Change the message sent by the client.','A disconnected socket is not ready for a send.'),
L('ready-state','Check connection state','readyState reports the current state. Inside open, it equals WebSocket.OPEN.',ws('server.on("connection", () => {});','client.on("open", () => { console.log(client.readyState === WebSocket.OPEN); client.close(); server.close(); });'),'true','Read the state before open and compare.','The connection can close later, so readiness is not a permanent promise.'),
L('binary','Receive bytes','A binary message carries bytes rather than text. This server sends three small byte values.',ws('server.on("connection", socket => socket.send(Buffer.from([1, 2, 3])));','client.on("message", (data, isBinary) => { console.log([...data].join(", ")); client.close(); server.close(); });'),'1, 2, 3','Send bytes 4, 5 and 6.','Do not decode arbitrary binary bytes as if they were normal text.'),
L('ping-pong','Check that a peer responds','Ping and pong are control messages. The ws client automatically answers a ping with pong.',ws('server.on("connection", socket => { socket.once("pong", () => socket.send("Still here")); socket.ping(); });',read_message),'Still here','Change the text sent after pong.','A real heartbeat needs a timeout for peers that never answer.'),
L('closing','Close with a reason','A close frame can carry a code and short reason. Code 1000 means a normal close.',ws('server.on("connection", socket => socket.close(1000, "Done"));','client.on("close", (code, reason) => { console.log(code + " " + reason.toString()); server.close(); });'),'1000 Done','Use a different short close reason.','A close event means messages can no longer be sent on that connection.'),
L('bad-json','Handle unreadable JSON','JSON.parse can fail. A catch block sends a friendly reply instead of crashing this handler.',ws('server.on("connection", socket => socket.on("message", data => { try { JSON.parse(data.toString()); socket.send("Valid JSON"); } catch { socket.send("Use valid JSON"); } }));','client.on("open", () => client.send("not json"));\n'+read_message),'Use valid JSON','Send {} instead.','Catch the parse failure and then check the parsed data shape separately.'),
L('size-limit','Limit message size','maxPayload limits incoming message bytes. The client sends five bytes to a server limited to four.',ws('server.on("connection", socket => { socket.on("error", () => {}); });','client.on("open", () => client.send("ABCDE"));\nclient.on("close", code => { console.log(code); server.close(); });',4),'1009','Send only four bytes and add an echo handler to see it accepted.','Keep limits clear; a message that is too large is closed with a protocol size error.')])
